# Example illustrating concepts (simplified, system specific details omitted)
# Compile shared library:
gcc -fPIC -shared -o libmymath.so mymath.c
# Compile program using shared library:
gcc -o myprogram myprogram.c -L. -lmymath
# mymath.c (shared library code):
double my_math_function(double x) { return x * 2; }
# myprogram.c (program using shared library):
#include <stdio.h>
#include "mymath.h"
int main() {
  double result = my_math_function(5.0);
  printf("Result: %f\n", result);
  return 0;
}
